use super::*;

/// Decide how to honour ONE mobile coordination request for `session`, from the folded coordination
/// state and the waiters whose dependencies have landed (`ready`).
///
/// Returns `None` when the session is not in a state the request can resolve. That is the security
/// property, not a convenience: the phone names a session id, and a plan is only ever produced for a
/// session the LOG shows parked — never for an arbitrary one a peer asked about.
///
/// * `approve` resolves ONLY a session paused for the user (`state.waiting`). A mere dependency
///   waiter is not a gate anyone paused, so approving one would resume a session on nobody's word.
/// * `wake` resolves a ready dependency waiter, and also a user-paused session (a phone "wake" on a
///   paused gate is a reasonable resume) — never an unknown session.
///
/// **A session that is both ready and paused takes the FRESH path.** A landed dependency is context
/// the live pane does not have, so it is relaunched rather than nudged; the `ready` arm is checked
/// first for exactly that reason and the case has its own test.
pub fn plan_mobile_resume(
    kind: CoordControlKind,
    session: &str,
    state: &CoordState,
    ready: &[Waiter],
) -> Option<MobileResume> {
    let paused = state.waiting.iter().find(|w| w.session == session);
    let inject = |w: &WaitingSession| MobileResume {
        session: session.to_string(),
        prompt: waiting_wake_prompt(w),
        via: ResumeVia::Inject,
    };
    match kind {
        CoordControlKind::Approve => paused.map(inject),
        CoordControlKind::Wake => match ready.iter().find(|w| w.session == session) {
            Some(w) => Some(MobileResume {
                session: session.to_string(),
                prompt: wake_prompt_for(w, state),
                via: ResumeVia::Fresh,
            }),
            None => paused.map(inject),
        },
    }
}
